globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2024,"grade":"1","contest":"КИТ","letters":"АБВГ","count":18,"language":"ru","points":3,"tasksFile":"1.pdf","answersFile":"reviewed-1.pdf","reviewedKey":true}, [{"title":"Таблица предметов","question":"Какого предмета нет в таблице?","choices":["Микроскоп","Телефон с клавиатурой","Велосипед","Видеокамера"],"answer":2,"points":3,"steps":["В верхнем ряду справа стоит микроскоп. Телефон найдётся в среднем ряду слева, а видеокамера — в нижнем слева.","Среди девяти предметов нет велосипеда. Он показан в варианте В."],"figure":{"src":"assets/kit/2024/1-01.webp","alt":"Три ряда по три предмета. Сверху монитор, серое устройство и микроскоп. В середине телефон, проектор и мышь. Снизу видеокамера, ноутбук и граммофон.","width":346,"height":290},"optionFigures":[{"src":"assets/kit/2024/1-01-a.webp","alt":"Микроскоп","width":66,"height":98},{"src":"assets/kit/2024/1-01-b.webp","alt":"Телефон с клавиатурой","width":122,"height":94},{"src":"assets/kit/2024/1-01-c.webp","alt":"Велосипед","width":142,"height":88},{"src":"assets/kit/2024/1-01-d.webp","alt":"Видеокамера","width":94,"height":96}]},{"title":"Подключение к компьютеру","question":"Какой из изображённых предметов не предназначен для подключения к компьютеру?","choices":["Серое устройство с лотками","Флешка","Видеокамера","Молоток"],"answer":3,"points":3,"steps":["Варианты А, Б и В показывают устройства, которые могут работать с компьютером. Например, с флешки и видеокамеры можно перенести файлы.","Молотком забивают гвозди. У него нет разъёма и он не передаёт данные компьютеру."],"optionFigures":[{"src":"assets/kit/2024/1-02-a.webp","alt":"Серое устройство с лотками","width":182,"height":128},{"src":"assets/kit/2024/1-02-b.webp","alt":"Флешка","width":152,"height":108},{"src":"assets/kit/2024/1-02-c.webp","alt":"Видеокамера","width":124,"height":128},{"src":"assets/kit/2024/1-02-d.webp","alt":"Молоток","width":120,"height":112}],"reviewedEdition":true},{"title":"Летает и плавает","question":"Какое из этих животных обычно передвигается и по воздуху, и вплавь?","choices":["Петух","Утка","Парусный корабль","Самолёт"],"answer":1,"points":3,"steps":["Петух может ненадолго взлететь, но не передвигается вплавь как водоплавающие птицы. Корабль и самолёт — транспорт.","Утка ходит по земле, летает и плавает по воде. Именно у неё оба способа движения обычны."],"optionFigures":[{"src":"assets/kit/2024/1-03-a.webp","alt":"Петух","width":106,"height":124},{"src":"assets/kit/2024/1-03-b.webp","alt":"Утка","width":118,"height":124},{"src":"assets/kit/2024/1-03-c.webp","alt":"Парусный корабль","width":138,"height":124},{"src":"assets/kit/2024/1-03-d.webp","alt":"Самолёт","width":204,"height":100}],"reviewedEdition":true},{"title":"Возможности смартфона","question":"Какую из этих вещей обычный смартфон не может заменить, выполнив её основную работу самостоятельно?","choices":["Пылесос","Пишущая машинка","Телефон","Фотоаппарат"],"answer":0,"points":3,"steps":["Со смартфона можно позвонить, набрать текст и сделать фотографию.","Пылесос втягивает пыль потоком воздуха. Смартфон этого делать не умеет."],"optionFigures":[{"src":"assets/kit/2024/1-04-a.webp","alt":"Пылесос","width":182,"height":134},{"src":"assets/kit/2024/1-04-b.webp","alt":"Пишущая машинка","width":160,"height":134},{"src":"assets/kit/2024/1-04-c.webp","alt":"Телефон","width":166,"height":128},{"src":"assets/kit/2024/1-04-d.webp","alt":"Фотоаппарат","width":152,"height":128}],"reviewedEdition":true},{"title":"Кто подарил подарок","question":"Камилла подарила подарки Арине и Белле, а Лена – Белле и Веронике. Какая схема соответствует условию задачи?","choices":["К → А и Б, Л → Б и В","К → А и дважды Б, Л → В","К → А, Л → В","К и Л → А, Б и В"],"answer":0,"points":3,"steps":["От К должны идти ровно две стрелки, к А и Б. От Л тоже две, к Б и В.","На схеме Б у Камиллы лишняя стрелка, а у Лены отсутствует стрелка к Белле. В схеме В Белла совсем без подарка. В схеме Г обе девочки дарят лишний подарок. Все условия выполняет схема А."],"optionFigures":[{"src":"assets/kit/2024/1-05-a.webp","alt":"К → А и Б, Л → Б и В","width":150,"height":140},{"src":"assets/kit/2024/1-05-b.webp","alt":"К → А и дважды Б, Л → В","width":150,"height":140},{"src":"assets/kit/2024/1-05-c.webp","alt":"К → А, Л → В","width":150,"height":140},{"src":"assets/kit/2024/1-05-d.webp","alt":"К и Л → А, Б и В","width":148,"height":140}]},{"title":"Имя на пенале","question":"Закрой пенал и прочти имя хозяйки.","choices":["Арина","Алина","Дина","Карина"],"answer":1,"points":3,"steps":["Придвинь нижние части букв к верхним и сравни ширину и направление штрихов.","При совмещении получается «АЛИНА». Вторая буква — Л, а третья — И."],"figure":{"src":"assets/kit/2024/1-06.webp","alt":"Верхние и нижние части букв разнесены на двух жёлтых полосках.","width":426,"height":104}},{"title":"Хоровод","question":"Алёша, Боря, Витя, Гриша и Дима водят хоровод. Алёша стоит справа от Вити, а Гриша – между Борей и Витей. Справа от Димы стоит…","choices":["Алёша","Боря","Витя","Гриша"],"answer":1,"points":3,"steps":["Двигайся по хороводу каждый раз к соседу справа. От Вити сразу попадёшь к Алёше. Слева от Вити стоит Гриша, а слева от Гриши — Боря.","Получается порядок Витя → Алёша → Дима → Боря → Гриша → Витя. Справа от Димы стоит Боря."]},{"title":"Тропа Красной Шапочки","question":"В каком доме живёт бабушка Красной Шапочки? Путь Красной Шапочки зашифрован знаками гриба и цветов в указанном порядке.","choices":["А","Б","В","Г"],"answer":1,"points":3,"steps":["От начала тропы на первой развилке выбери ветку с грибом. Она ведёт влево.","На второй развилке выбери ветку с цветами. Она поворачивает вправо к домику Б."],"figure":{"src":"assets/kit/2024/1-08.webp","alt":"У Красной Шапочки ветка с грибом влево и ветка с цветами вправо. У каждой из них есть ещё по две ветки, слева с грибом и справа с цветами. Домики подписаны А, Б, В, Г слева направо.","width":342,"height":246}},{"title":"Пирамида сверху","question":"Какой вид сверху соответствует пирамиде?","choices":["Три окружности и точка","Четыре окружности и точка","Пять окружностей и точка","Шесть окружностей и точка"],"answer":1,"points":3,"steps":["На виде сбоку видны три круглые ступени и верхняя деталь с острым кончиком. Сверху ступени дают три окружности с одним центром.","Верхняя деталь даёт ещё одну окружность и точку в центре. Всего четыре окружности и точка."],"figure":{"src":"assets/kit/2024/1-09.webp","alt":"Снизу вверх три круглые ступени, на самой узкой стоит деталь с острым верхним кончиком.","width":92,"height":86},"optionFigures":[{"src":"assets/kit/2024/1-09-a.webp","alt":"Три окружности и точка","width":76,"height":76},{"src":"assets/kit/2024/1-09-b.webp","alt":"Четыре окружности и точка","width":100,"height":94},{"src":"assets/kit/2024/1-09-c.webp","alt":"Пять окружностей и точка","width":124,"height":120},{"src":"assets/kit/2024/1-09-d.webp","alt":"Шесть окружностей и точка","width":158,"height":158}]},{"title":"Разорванная записка","question":"Прочитай разорванную записку.","choices":["клоун","колун","уклон","кулон"],"answer":0,"points":3,"steps":["У фрагмента «К» слева ровный край, поэтому он первый. Выступ слева на «ЛО» подходит к выемке на «К».","После «ЛО» ставим «У». Остаётся «Н» с закруглённым внешним краем. Вместе читаем «КЛОУН»."],"figure":{"src":"assets/kit/2024/1-10.webp","alt":"Слева направо детали с буквами У, Н, К и ЛО. У каждой детали свой контур.","width":388,"height":88}},{"title":"Складской робот","question":"Складской робот выполняет единственную команду «Найти предмет на (номер полки; номер места) и выдать его». Какой предмет выдаст робот, выполняя команду «Найти предмет на (2; 3) и выдать его»?","choices":["Светлый сапог со шпорой","Кед с высокой шнуровкой","Тёмный ботинок","Низкий светлый кед"],"answer":3,"points":4,"steps":["Первое число команды — 2. Оно указывает вторую полку сверху.","Второе число — 3. Отсчитай три места слева направо. На третьем месте лежит низкий светлый кед из варианта Г."],"figure":{"src":"assets/kit/2024/1-11.svg","alt":"Четыре полки, на каждой по три предмета слева направо. Полка 1: чёрный ботинок, сапог со шпорой, балетка. Полка 2: туфля, подошва, низкий кед. Полка 3: сапог, чёрная туфля, подошва. Полка 4: светлая туфля, высокий кед, чёрная туфля.","width":300,"height":312},"optionFigures":[{"src":"assets/kit/2024/1-11-a.webp","alt":"Светлый сапог со шпорой","width":86,"height":94},{"src":"assets/kit/2024/1-11-b.svg","alt":"Кед с высокой шнуровкой","width":86,"height":66},{"src":"assets/kit/2024/1-11-c.webp","alt":"Тёмный ботинок","width":96,"height":84},{"src":"assets/kit/2024/1-11-d.svg","alt":"Низкий светлый кед","width":92,"height":62}]},{"title":"Буквы по кругу","question":"Какую букву надо добавить, чтобы можно было прочитать слово по кругу?","choices":["А","Е","И","О"],"answer":0,"points":4,"steps":["Начни с нижней из двух букв К справа и читай по часовой стрелке. Получится «КАРМ_ШЕК».","Если вставить А, получится слово «КАРМАШЕК»."],"figure":{"src":"assets/kit/2024/1-12.webp","alt":"Круг из восьми секторов. По часовой стрелке от верхнего правого сектора стоят Е, К, К, А, Р, М, пустой сектор, Ш.","width":192,"height":192}},{"title":"Серый пункт меню","question":"Что произойдёт, если кликнуть мышкой по светло-серому слову Повторить?","choices":["ничего не произойдёт","текст станет чёрным","произойдёт повтор","текст исчезнет"],"answer":0,"points":4,"steps":["Сравни строки «Отменить» и «Повторить». Затемнённая строка «Отменить» доступна, светло-серый пункт «Повторить» сейчас отключён.","Клик по отключённому пункту не запускает команду. Ничего не произойдёт."],"figure":{"src":"assets/kit/2024/1-13.webp","alt":"Меню «Правка». Среди чёрных пунктов светло-серым выделен «Повторить».","width":338,"height":262}},{"title":"Ягоды для компота","question":"Сколько всего разных компотов можно сварить из ягод двух видов, если у повара есть вишня, виноград и земляника? Компоты различаются только составом ягод, без учёта пропорций.","choices":["5","6","3","4"],"answer":2,"points":4,"steps":["Возьми сначала вишню. К ней можно добавить виноград или землянику, получив два компота.","Без вишни остаётся одна пара, виноград с земляникой. Порядок добавления ягод ничего не меняет. Всего три компота."],"reviewedEdition":true},{"title":"Сравнение двух квадратов","question":"Закрась чёрным клетки квадратов, в которых стоят одинаковые числа, а белым – где разные. Что получилось?","choices":["Белые углы сверху и белая середина снизу","Чёрные верхние углы и нижняя середина","Белые углы и белый центр","Чёрные углы и чёрный центр"],"answer":3,"points":4,"steps":["Сравни числа в клетках на одинаковых местах. Сверху совпадают 1 и 6 по краям, в середине совпадает 7, снизу совпадают 2 и 4 по краям.","Закрашены четыре угла и центральная клетка. Это рисунок Г."],"figure":{"src":"assets/kit/2024/1-15.webp","alt":"Два квадрата 3 на 3. Ряды первого: 1 3 6, 5 7 8, 2 9 4. Ряды второго: 1 5 6, 9 7 3, 2 8 4.","width":300,"height":138},"optionFigures":[{"src":"assets/kit/2024/1-15-a.webp","alt":"Белые углы сверху и белая середина снизу","width":124,"height":124},{"src":"assets/kit/2024/1-15-b.webp","alt":"Чёрные верхние углы и нижняя середина","width":122,"height":124},{"src":"assets/kit/2024/1-15-c.webp","alt":"Белые углы и белый центр","width":120,"height":120},{"src":"assets/kit/2024/1-15-d.webp","alt":"Чёрные углы и чёрный центр","width":120,"height":120}]},{"title":"Кастрюля и банка","question":"Имеются девятилитровая кастрюля, четырёхлитровая банка, водопроводный кран и раковина для слива воды. Сосуды сначала пустые. Их можно наполнять из крана доверху, полностью сливать воду и переливать её из одного сосуда в другой, пока первый не опустеет или второй не наполнится. Сколько литров воды из крана нужно потратить как минимум, чтобы в кастрюле оказалось 7 литров?","choices":["9","13","16","18"],"answer":2,"points":5,"steps":["Трижды наполни банку из крана и переливай воду в кастрюлю. При третьем переливании в кастрюле будет 9 л, а в банке останутся 3 л. Опорожни кастрюлю и перелей в неё эти 3 л. Ещё одна полная банка даёт 7 л в кастрюле. Потрачено 4 × 4 = 16 л.","Проверь меньший расход, перебирая пары «литры в кастрюле, литры в банке» от (0, 0). При заполнении до края прибавляй к расходу только долитый объём. Слив и переливание до пустого или полного сосуда расход не меняют. При ограничении в 15 л в кастрюле получаются только 0, 1, 3, 4, 5, 8 и 9 л, поэтому 7 л требуют как минимум 16 л."],"reviewedEdition":true},{"title":"Остров честных и лгунов","question":"Путешественник попал на остров честных и лгунов (честные всегда говорят правду, а лгуны всегда лгут) и поговорил с двумя островитянами – Аа и Ба. Аа сказал: «Я – единственный честный житель на этом острове». Ба сказал: «Да, это правда». Выбери правильное утверждение.","choices":["Аа – честный, Ба – лжец","Аа и Ба – лжецы","Аа – лжец, Ба – честный","Аа и Ба – честные"],"answer":1,"points":5,"steps":["Оба утверждают, что Аа — единственный честный. Значит, их утверждения либо оба верны, либо оба ложны. Варианты с одним честным и одним лжецом отпадают.","Если оба честны, на острове уже есть два честных жителя. Это противоречит их словам. Значит, оба лжецы."]},{"title":"Пять равных сумм","question":"Расставь все числа от 1 до 7 в кружки так, чтобы сумма вдоль всех пяти линий была одинакова. Какое число стоит в верхнем кружке?","choices":["1","2","7","4"],"answer":3,"points":5,"steps":["Обозначь верхнее число через x, а сумму вдоль линии через S. Две горизонтали покрывают все числа, кроме x. Сумма от 1 до 7 равна 28, поэтому 2S = 28 − x.","Три линии от вершины покрывают остальные шесть кружков по разу, а вершину — трижды. Значит, 3S = 28 + 2x. Из этих двух равенств получаем 7x = 28 и x = 4.","Проверка расстановкой: вершина 4, средний ряд 1, 5, 6, нижний ряд 7, 3, 2. На каждой линии сумма 12."],"figure":{"src":"assets/kit/2024/1-18.webp","alt":"Треугольник: один кружок вверху, три в среднем ряду и три внизу. Пять линий проходят вдоль двух горизонталей и от вершины через каждый кружок среднего ряда к кружку внизу.","width":344,"height":222}}]);
edition.sources.readers = {"tasksUrl":"assets/kit/2024/1-reading.pdf"};
register(edition, globalThis.KENGURU_CHOICE_LAYOUTS, {});
